def select_next_node(graph, unvisited_nodes):
    max_core = graph.graph['precomputed']['max_core_k']

    def structural_fragility_index(node):
        betweenness = graph.nodes[node]['betweenness']
        core_norm = graph.nodes[node]['core_number'] / max_core
        eigenvector = graph.nodes[node]['eigenvector']
        clustering = graph.nodes[node]['clustering']
        return (betweenness * core_norm * eigenvector) / (clustering + 1e-6)

    return max(unvisited_nodes, key=structural_fragility_index)
